class CardInterpreter:
    COUNTER_TOKEN_ACTIVATION = re.compile(
        r"^\{1\}, \{T\}, Sacrifice this (?:token|artifact): Put a \+1/\+1 counter "
        r"on target creature\. Activate only as a sorcery\.$",
        re.I,
    )
    LANDCYCLING = re.compile(
        r"^(?P<land>Plains|Island|Swamp|Mountain|Forest)cycling "
        r"(?P<cost>\{[0-9]+\}) \(\2, Discard this card: Search your library "
        r"for an? (?P=land) card, reveal it, put it into your hand, then shuffle\.\)$",
        re.I,
    )
    RAY_FILLET_DRAW = re.compile(
        r"^\{2\}, Remove a \+1/\+1 counter from a creature you control: Draw a card\.$"
    )
    TOKEN_HASTE = re.compile(
        r"^\{R\}, \{T\}: Creature tokens you control gain haste until end of turn\.$"
    )
    ROCK_SOLDIERS_ETB = "When this creature enters, destroy up to one target noncreature artifact."
    ARTIFACT_ENTRY_SELF_COUNTER = re.compile(
        r"^Whenever an artifact you control enters, put a \+1/\+1 counter on (?P<source>.+)\.$"
    )
    FUGITIVE_COUNTER = re.compile(
        r"^\{U\}, Sacrifice this creature: Counter target spell that targets an artifact "
        r"or creature you control\.$"
    )
    CANT_ATTACK_UNLESS_ANOTHER_ARTIFACT = re.compile(
        r"^This creature can't attack unless you control another artifact\.$"
    )

    """Derive reusable executable constructs without legality, mutation, or strategy."""

    STATIC_OTHER_CREATURES = re.compile(
        r"^.+ gets \+(\d+)/\+(\d+) for each other creature you control\.$"
    )
